```ts
export class JobQueue {
  private pending: Array<() => Promise<void>> = [];
  private active = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(
    private readonly concurrency: number,
    private readonly maxRetries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        // chisle: retries are immediate and keep their slot; add backoff if jobs hit rate-limited services
        for (let attempt = 0; ; attempt++) {
          try {
            return resolve(await job());
          } catch (err) {
            if (attempt >= this.maxRetries) return reject(err);
          }
        }
      });
      this.next();
    });
  }

  /** Resolves once nothing is running or queued, whether jobs succeeded or failed. */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise<void>((resolve) => this.idleWaiters.push(resolve));
  }

  private isIdle(): boolean {
    return this.active === 0 && this.pending.length === 0;
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.active++;
      void run().finally(() => {
        this.active--;
        this.next();
        if (this.isIdle()) {
          for (const wake of this.idleWaiters.splice(0)) wake();
        }
      });
    }
  }
}
