const pool = new pg.Pool(); // reads PG* environment variables
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.created_at_text, String(row.id)])).toString("base64url");

function decodeCursor(cursor) {
  try {
    const [createdAt, id] = JSON.parse(Buffer.from(cursor, "base64url").toString());
    if (typeof createdAt === "string" && typeof id === "string") return [createdAt, id];
  } catch {}
  return null;
}

router.get("/orders", async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer from 1 to ${MAX_LIMIT}` });
  }

  let after = null;
  if (req.query.cursor !== undefined) {
    after = typeof req.query.cursor === "string" ? decodeCursor(req.query.cursor) : null;
    if (!after) return res.status(400).json({ error: "invalid cursor" });
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to
    // milliseconds and the next page would skip or repeat rows.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS created_at_text
         FROM orders
        ${after ? "WHERE (created_at, id) < ($2::timestamptz, $3)" : ""}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...(after ?? [])], // one extra row tells us whether another page exists
    );

    const page = rows.slice(0, limit);
    res.json({
      data: page.map(({ created_at_text, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // Class 22 = data exception: the cursor decoded but held a bad timestamp or id.
    if (err.code?.startsWith("22")) return res.status(400).json({ error: "invalid cursor" });
    next(err);
  }
});

export default router;
